/* ==========================================================================
 *  ingame/enemy/enemy_dat.c
 *
 *  The game's two static enemy tables, plus the small amount of state that
 *  travels with them: why each entry was last released from the field.
 *
 *  jene_dat[] holds hostile ghosts -- the ones with HP, an attack pattern and
 *  a combat algorithm.  aene_dat[] holds the passive ones that exist to be
 *  photographed or to walk a route.  Both are addressed as (ene_type, dat_no)
 *  pairs from ev_ene.c and enemy.c; ene_type 0 selects jene_dat and 2 selects
 *  aene_dat.
 *
 *  Both tables were read straight out of SLES_523.84's .data (ROM 0x3011b8 and
 *  0x309f18) -- Ghidra does not show initialiser contents.  They sit at the end
 *  of the file because the ROM's line stabs put the first function at line 88,
 *  which is far too early for 517 records to have preceded it; the declarations
 *  the functions need come from enemy_dat.h instead.
 *
 *  One curiosity worth recording: enemy_dat.o's .rodata carries the string
 *  "ene_release_now_count is Over ENE_RELEASE_MAX_NO" and a __FUNCTION__ entry
 *  for release_typeRegister, but no instruction in the object references
 *  either.  The bounds check they belonged to was compiled out before this
 *  build, so it is deliberately not reconstructed here.
 *
 *  Reconstructed from the Feb 6 2004 prototype (SLES_523.84), enemy_dat.o.
 * ======================================================================== */

#include "enemy_dat.h"
#include "../../common/utility2.h"              /* PRINT_ASSERT         */

/* Release reason per entry, indexed the same way the tables are.  These are
 * the only part of enemy_dat.o that is not read-only, and both go to the
 * memory card verbatim. */
static ENE_DAT_SAVE jene_dat_save[JENE_DAT_MAX];
static ENE_DAT_SAVE aene_dat_save[AENE_DAT_MAX];

/* --------------------------------------------------------------------------
 *  Battle ghost placement
 *
 *  A battle event picks one of the reserved tail entries and writes the spawn
 *  transform in before requesting the load.
 * ----------------------------------------------------------------------- */

void SetBattleEneDatPos(int dat_no, float *vec)                         /* 88 */
{
    if ((dat_no < BATTLE_ENE_DAT_TOP) || (JENE_DAT_MAX <= dat_no))      /* 90 */
    {
        PRINT_ASSERT("dat_no %d is invalid", dat_no);                   /* 92 */
        return;
    }

    jene_dat[dat_no].cmn.px = vec[0];                                   /* 97 */
    jene_dat[dat_no].cmn.py = vec[1];                                   /* 98 */
    jene_dat[dat_no].cmn.pz = vec[2];                                   /* 99 */
}

void SetBattleEneDatRot(int dat_no, int iRot)                          /* 103 */
{
    if ((dat_no < BATTLE_ENE_DAT_TOP) || (JENE_DAT_MAX <= dat_no))     /* 105 */
    {
        PRINT_ASSERT("dat_no %d is invalid", dat_no);                  /* 107 */
        return;
    }

    jene_dat[dat_no].cmn.dir = (u_short)iRot;                          /* 112 */
}

/* --------------------------------------------------------------------------
 *  Release type
 * ----------------------------------------------------------------------- */

void release_typeSetSaveJ(MC_SAVE_DATA *save)
{
    save->addr = (u_char *)jene_dat_save;                              /* 152 */
    save->size = sizeof(jene_dat_save);                                /* 153 */
}

void release_typeSetSaveA(MC_SAVE_DATA *save)
{
    save->addr = (u_char *)aene_dat_save;                              /* 157 */
    save->size = sizeof(aene_dat_save);                                /* 158 */
}

/* Empty in this build.  ingame.c still calls it on every room teardown, so the
 * entry point is kept rather than folded away. */
void release_typeClear(void)                                           /* 163 */
{
}

void release_typeInit(void)
{
    for (int i = 0; i < JENE_DAT_MAX; i++) {                           /* 167 */
        jene_dat_save[i].release_type = ENE_RELEASE_NO_RELEASE;        /* 168 */
    }
    for (int i = 0; i < AENE_DAT_MAX; i++) {                           /* 170 */
        aene_dat_save[i].release_type = ENE_RELEASE_NO_RELEASE;        /* 171 */
    }
}

void release_typeRegister(int ene_type, int dat_no, ENE_RELASE_TYPE type)
{
    if (ene_type == 0) {                                               /* 185 */
        jene_dat_save[dat_no].release_type = (char)type;               /* 187 */
    }
    else if (ene_type == 2) {                                          /* 189 */
        aene_dat_save[dat_no].release_type = (char)type;               /* 190 */
    }
}                                                                      /* 193 */

ENE_RELASE_TYPE release_typeGetReleaseType(int ene_type, int dat_no)
{
    ENE_RELASE_TYPE ret;

    if (ene_type == 0) {                                               /* 201 */
        ret = (ENE_RELASE_TYPE)jene_dat_save[dat_no].release_type;     /* 203 */
    }
    else if (ene_type == 2) {                                          /* 205 */
        ret = (ENE_RELASE_TYPE)aene_dat_save[dat_no].release_type;     /* 206 */
    }
    else {
        /* Neither table -- an unregistered ghost has never been released. */
        ret = ENE_RELEASE_NO_RELEASE;
    }

    return ret;                                                        /* 215 */
}

